#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"; helper="$root/.github/scripts/ci-compiled-server.sh"; installer="$root/.github/scripts/ci-install-hurl.sh"; wf="$root/.github/workflows/ci.yml"; BASH_RUN="${BASH:-bash}"; pass=0; fail=0; oracle_root="$root"
contract() { python3 -c 'exec('"'"'import json\nimport os\nimport sys\n\nroot = sys.argv[1]\n\n\ndef read(path):\n    with open(os.path.join(root, path), encoding="utf-8") as handle:\n        return handle.read()\n\n\ndef active_shell(source):\n    return [line for line in source.splitlines() if line.strip() and not line.lstrip().startswith("#")]\n\n\ndef shell_shape(lines):\n    output = []\n    pending = ""\n    for line in lines:\n        piece = line.strip()\n        pending = (pending + " " + piece).strip() if pending else piece\n        if pending.endswith("\\\\"):\n            pending = pending[:-1].rstrip()\n        else:\n            output.append(" ".join(pending.split()))\n            pending = ""\n    if pending:\n        raise ValueError\n    return output\n\n\ndef markdown(source):\n    outside = []\n    fences = []\n    inside = None\n    comment = False\n    for line in source.splitlines():\n        stripped = line.strip()\n        if comment:\n            if "-->" in stripped:\n                comment = False\n            continue\n        if stripped.startswith("<!--"):\n            comment = "-->" not in stripped\n            continue\n        marker = stripped[:3]\n        if inside:\n            if marker == inside:\n                fences.append(current)\n                inside = None\n            else:\n                current.append(line)\n        elif marker in ("```", "~~~"):\n            inside = marker\n            current = []\n        elif stripped:\n            outside.append(line)\n    if comment or inside:\n        raise ValueError\n    return outside, fences\n\n\ndef active_yaml(source):\n    return [line for line in source.splitlines() if line.strip() and not line.lstrip().startswith("#")]\n\n\ndef same(lines, prefix, expected):\n    if [line for line in lines if line.startswith(prefix)] != [expected]:\n        raise ValueError\n\n\ndef one(lines, expected):\n    if lines.count(expected) != 1:\n        raise ValueError\n\n\ndef section(source, begin, end):\n    if source.count(begin) != 1 or source.count(end) != 1:\n        raise ValueError\n    return source.split(begin, 1)[1].split(end, 1)[0]\n\n\ndef ykey(line, indent):\n    if "\\t" in line or not line.startswith(" " * indent) or line.startswith(" " * (indent + 1)):\n        raise ValueError\n    text = line[indent:]\n    if text.count(":") != 1:\n        raise ValueError\n    name, value = text.split(":")\n    name = name.strip()\n    if len(name) > 1 and name[:1] == name[-1:] and name[:1] in ("\'"'"'", \'"'"'"\'"'"'):\n        if "\\\\" in name:\n            raise ValueError\n        name = name[1:-1]\n    if not name or not name[0].isalpha() or not all(char.isalnum() or char in "_-" for char in name):\n        raise ValueError\n    return name, value.strip()\n\n\ndef scalar(value):\n    return len(value) > 2 and value[:1] == value[-1:] == \'"'"'"\'"'"' and "\\\\" not in value\n\n\ntry:\n    installer = shell_shape(active_shell(read(".github/scripts/ci-install-hurl.sh")))\n    if installer != [\n        "set -euo pipefail",\n        "HURL_URL=https://github.com/Orange-OpenSource/hurl/releases/download/8.0.1/hurl-8.0.1-x86_64-unknown-linux-gnu.tar.gz",\n        "HURL_SHA256=cac7c4670d69444db120edb21fe06c97ba8c80dcc52279957c8dd18f05fb0c06",\n        "tool_dir=\\"${RUNNER_TEMP}/hurl-8.0.1\\"",\n        "mkdir -p \\"$tool_dir\\"",\n        "archive=\\"${tool_dir}/hurl-8.0.1-x86_64-unknown-linux-gnu.tar.gz\\"",\n        "curl --fail --location --retry 3 --retry-delay 2 --retry-max-time 60 --connect-timeout 15 --max-time 120 --output \\"$archive\\" \\"$HURL_URL\\"",\n        "actual=\\"$(sha256sum \\"$archive\\" | awk \'"'"'{print $1}\'"'"')\\"",\n        "[ \\"$actual\\" = \\"$HURL_SHA256\\" ] || { echo \\"Hurl archive digest mismatch: expected ${HURL_SHA256}, got ${actual}\\" >&2; exit 1; }",\n        "tar -xzf \\"$archive\\" -C \\"$tool_dir\\"",\n        "bin_dir=\\"${tool_dir}/hurl-8.0.1-x86_64-unknown-linux-gnu/bin\\"",\n        "test -x