/@playwright/test"]\n    playwright = lock["packages"]["node_modules/playwright"]\n    core = lock["packages"]["node_modules/playwright-core"]\n    version = test["version"]\n    if not all(isinstance(package.get(field), str) and package[field] for package in (test, playwright, core) for field in ("version", "resolved", "integrity")):\n        raise ValueError\n    if playwright["version"] != version or core["version"] != version or test["dependencies"].get("playwright") != version or playwright["dependencies"].get("playwright-core") != version:\n        raise ValueError\n\n    agents = read("AGENTS.md")\n    directory = section(agents, "## Directory Map", "### Module Boundaries")\n    matrix = section(agents, "## Verification Matrix", "## Important Development Notes")\n    enforcement = section(agents, "## Enforcement Index", "阈值与正则")\n    agent_rows, _ = markdown(agents)\n    directory_rows, directory_fences = markdown(directory)\n    matrix_rows, matrix_fences = markdown(matrix)\n    enforcement_rows, enforcement_fences = markdown(enforcement)\n    if any("READINESS GAP" in line for line in agent_rows) or directory_rows or len(directory_fences) != 1 or matrix_fences or enforcement_fences or any(line.lstrip().startswith("<") for line in matrix_rows + enforcement_rows):\n        raise ValueError\n    one(directory_fences[0], "smoke/      Hurl HTTP 冒烟用例与深链 exact-byte fixture")\n    one(matrix_rows, "| HTTP smoke | Hurl（调用方拥有已运行服务） | `make smoke` | 退出码 0；真实 HTTP 断言全绿 |")\n    one(matrix_rows, "| UI 走查 | Playwright Chromium（调用方拥有已运行服务） | `make ui-walk` | 退出码 0；真实浏览器走查与 error oracle 全绿 |")\n    one(enforcement_rows, "| HTTP smoke | `.github/workflows/ci.yml`（job `smoke`） | `make smoke` + CI `smoke`/`all-checks-passed` | block |")\n    one(enforcement_rows, "| UI 走查 | `.github/workflows/ci.yml`（job `ui-walk`） | `make ui-walk` + CI `ui-walk`/`all-checks-passed` | block |")\n\n    lines = active_yaml(section(read("constraints.yaml"), "verification:\\n", "\\nexemptions:"))\n    expected = ("static", "types", "unit", "drift", "full", "guardrails", "smoke", "ui-walk")\n    fields = ("command", "evidence", "required_at")\n    surfaces = {}\n    if not lines or lines.pop(0) != "  surfaces:":\n        raise ValueError\n    while lines and lines[0] != "  enforced_by: \\"AGENTS.md 验证矩阵 ↔ 本段双向镜像 + Makefile 目标存在性检查\\"":\n        name, value = ykey(lines.pop(0), 4)\n        if value or name not in expected or name in surfaces:\n            raise ValueError\n        parsed = []\n        while lines and lines[0].startswith("      "):\n            field, value = ykey(lines.pop(0), 6)\n            if field not in fields or field in (item[0] for item in parsed) or not scalar(value):\n                raise ValueError\n            parsed.append((field, value))\n        if tuple(field for field, value in parsed) != fields:\n            raise ValueError\n        surfaces[name] = parsed\n    if tuple(surfaces) != expected or lines != ["  enforced_by: \\"AGENTS.md 验证矩阵 ↔ 本段双向镜像 + Makefile 目标存在性检查\\""]:\n        raise ValueError\n    wanted = {\n        "smoke": [("command", \'"'"'"make smoke"\'"'"'), ("evidence", \'"'"'"exit-code; real HTTP assertions on caller-owned service"\'"'"'), ("required_at", \'"'"'"L2+"\'"'"')],\n        "ui-walk": [("command", \'"'"'"make ui-walk"\'"'"'), ("evidence", \'"'"'"exit-code; Chromium journey on caller-owned service"\'"'"'), ("required_at", \'"'"'"L2+"\'"'"')],\n    }\n    if any(surfaces[name] != value for name, value in wanted.items()):\n        raise ValueError\n\n    makefile = read("Makefile")\n    make_lines = makefile.splitlines()\n    conditional = defined = 0\n    headers = {}\n    safe_overrides = ("SHELL := /bin/bash", "SMOKE_BASE_URL ?= http://127.0.0.1:3000", "override SMOKE_BASE_URL := $(value SMOKE_BASE_URL)", "UI_WALK_BASE_URL ?= http://127.0.0.1:3000", "override UI_WALK_BASE_URL := $(value UI_WALK_BASE_URL)")\n    for index, line in enumerate(make_lines):\n        stripped = line.strip()\n        if not stripped or stripped.startswith("#") or line.startswith("\\t"):\n            continue\n        head, separator, tail = line.partition(":")\n        targets = head.split()\n        equal = line.find("=")\n        assignment = (separator and tail.startswith("=")) or (equal >= 0 and (not separator or equal < line.find(":"))) or tail.startswith(":=")\n        if assignment and stripped not in safe_overrides:\n            raise ValueError\n        if not assignment and ("$" in head or chr(92) in head or (separator and (not targets or any(char in head for char in "$%&*?[]") or ":" in tail.split("#", 1)[0] or ";" in tail.split("#", 1)[0]))):\n            raise ValueError\n        for name in ("smoke", "ui-walk"):\n            if not assignment and separator and name in targets:\n                if conditional or defined or name in headers or targets != [name] or head != name or (tail.lstrip() and not tail.lstrip().startswith("##")):\n                    raise ValueError\n                headers[name] = index\n        directive = stripped.split(None, 1)[0]\n        if directive in ("ifeq", "ifneq", "ifdef", "ifndef"):\n            conditional += 1\n        elif directive == "endif":\n            conditional -= 1\n            if conditional < 0:\n                raise ValueError\n        elif directive == "define":\n            defined += 1\n        elif directive == "endef":\n            defined -= 1\n            if defined < 0:\n                raise ValueError\n        elif directive in ("include", "-include", "sinclude") or (not assignment and any(token in stripped for token in ("$(eval", "$( eval", "${eval", "${ eval", "$(call", "${call", "$(foreach", "${foreach", "$(value", "${value"))) or (directive == "override" and stripped not in safe_overrides):\n            raise ValueError\n    phony = [word for line in active_shell(makefile) if line.startswith(".PHONY:") for word in line.split(":", 1)[1].split()]\n    if conditional or defined or set(headers) != {"smoke", "ui-walk"} or phony.count("smoke") != 1 or phony.count("ui-walk") != 1:\n        raise ValueError\n\n    def recipes(name, expected):\n        output = []\n        index = headers[name] + 1\n        while index < len(make_lines):\n            line = make_lines[index]\n            stripped = line.strip()\n            if not stripped or stripped.startswith("#"):\n                index += 1\n                continue\n            if not line.startswith("\\t"):\n                break\n            command = line[1:].lstrip()\n            if command.startswith("@"):\n                command = command[1:].lstrip()\n            if not command.startswith("#"):\n                output.append(line)\n            index += 1\n        if output != expected:\n            raise ValueError\n\n    recipes("smoke", [\n        "\\t@/usr/bin/env -i PATH=\\"$$PATH\\" /bin/sh -c \'"'"'command -v hurl >/dev/null 2>&1\'"'"' || { echo \\"错误：未找到 hurl；安装说明：https://hurl.dev/docs/installation.html\\" >&2; exit 1; }",\n        "\\t/usr/bin/env -i PATH=\\"$$PATH\\" hurl --test --jobs 1 --retry 0 --variable \\"base_url=$${SMOKE_BASE_URL}\\" smoke/public.hurl smoke/auth.hurl",\n    ])\n    recipes("ui-walk", ["\\tnpm run ui-walk --workspace web"])\nexcept Exception:\n    sys.exit(1)\n'"'"')' "$1"; }
ccopy() { local source_root="$root"; contract_copy="$scratch/contract"; rm -rf "$contract_copy"; mkdir -p "$contract_copy/.github/scripts" "$contract_copy/web"; cp "$source_root/.github/scripts/ci-install-hurl.sh" "$source_root/.github/scripts/ci-compiled-server.sh" "$contract_copy/.github/scripts/"; cp "$source_root/web/package.json" "$contract_copy/web/"; cp "$source_root/package-lock.json" "$source_root/AGENTS.md" "$source_root/constraints.yaml" "$source_root/Makefile" "$contract_copy/"; }; cm() { ccopy; if ed "$contract_copy/$2" r "$3" "$4" "$contract_copy/$2"; then if contract "$contract_copy"; then rc=0; else rc=$?; fi; record "$1" "$rc" "${5:-1}"; else echo "FAIL $1 missing anchor"; fail=$((fail+1)); fi; }; cj() { ccopy; if python3 -c 'import json,os,sys;from functools import reduce;r,m=sys.argv[1:];q={"decl":("web/package.json",["devDependencies","@playwright/test"],"^0.0.0"),"test":("package-lock.json",["packages","node_modules/@playwright/test","dependencies","playwright"],"0.0.0"),"core":("package-lock.json",["packages","node_modules/playwright","dependencies","playwright-core"],"0.0.0"),"resolved":("package-lock.json",["packages","node_modules/playwright-core","resolved"],""),"integrity":("package-lock.json",["packages","node_modules/playwright-core","integrity"],"")};p,ks,n=q[m];f=os.path.join(r,p);d=json.load(open(f));x=reduce(dict.__getitem__,ks[:-1],d);k=ks[-1];sys.exit(2) if not isinstance(x.get(k),str) or not x[k] or x[k]==n else None;x[k]=n;open(f,"w").write(json.dumps(d))' "$contract_copy" "$2"; then if contract "$contract_copy"; then rc=0; else rc=$?; fi; record "$1" "$rc" 1; else echo "FAIL $1 structure field"; fail=$((fail+1)); fi; }; hp() { ccopy; if ed "$contract_copy/.github/scripts/ci-compiled-server.sh" r 'sanitize() {' $':\nsanitize() {' "$contract_copy/.github/scripts/ci-compiled-server.sh"; then if contract "$contract_copy"; then rc=0; else rc=$?; fi; record "$1" "$rc" 0; else echo "FAIL $1 missing anchor"; fail=$((fail+1)); fi; }
record() { if [ "$2" -eq "$3" ]; then echo "PASS $1 (rc=$2)"; pass=$((pass+1)); else echo "FAIL $1 (rc=$2 want=$3)"; fail=$((fail+1)); fi; }
expect_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "PASS $1"; pass=$((pass+1)); else echo "FAIL $1"; fail=$((fail+1)); fi; }
reject_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "FAIL $1"; fail=$((fail+1)); else echo "PASS $1"; pass=$((pass+1)); fi; }
scratch=$(mktemp -d); trap 'rm -rf "$scratch"' EXIT; mkdir -p "$scratch/bin" "$scratch/rt" "$scratch/static" "$scratch/install"
write_bin() { printf '%s\n' "$2" > "$scratch/bin/$1"; chmod +x "$scratch/bin/$1"; }
term_node() { printf '%s\n' '#!/bin/sh' 'echo $$ > "$RUNNER_TEMP/node.pid"' "trap \"exit $1\" TERM" 'while true; do sleep 0.05; done' > "$scratch/bin/node"; chmod +x "$scratch/bin/node"; }
ok_make() { write_bin make $'#!/bin/sh\n[ "$1" = "$EXPECT_TARGET" ] || exit 9\necho fake make ok; exit 0'; }
alive_pid() { [ -f "$1" ] && kill -0 "$(cat "$1")" 2>/dev/null; }
pid_of() { [ -f "$1" ] && cat "$1" || true; }
assert_dead() { if alive_pid "$1"; then echo "FAIL $2"; fail=$((fail+1)); kill -KILL "$(cat "$1")" 2>/dev/null || true; else echo "PASS $2"; pass=$((pass+1)); fi; }
reap_pids() { for p in "$@"; do [ -n "${p:-}" ] && kill -KILL "$p" 2>/dev/null || true; k=0; while [ -n "${p:-}" ] && [ "$k" -lt 40 ] && kill -0 "$p" 2>/dev/null; do sleep 0.05; k=$((k+1)); done; done; }
ck_sent() { if kill -0 "$1" 2>/dev/null; then echo "PASS $2"; pass=$((pass+1)); kill -TERM "$1" 2>/dev/null || true; wait "$1" 2>/dev/null || true; else echo "FAIL $2"; fail=$((fail+1)); fi; }
with_h() { PATH="$scratch/bin:/usr/bin:/bin" RUNNER_TEMP="$scratch/rt" HOST=127.0.0.1 PORT=18016 SMOKE_BASE_URL=http://127.0.0.1:18016 UI_WALK_BASE_URL=http://127.0.0.1:18016 DB_PATH="$scratch/rt/app.db" STATIC_ROOT="$scratch/static" EXPECT_TARGET="${EXPECT_TARGET:-smoke}" CI_TERM_WAIT="${CI_TERM_WAIT:-2}" CI_KILL_WAIT="${CI_KILL_WAIT:-1}" CI_READY_SLEEP="${CI_READY_SLEEP:-0.05}" "$@"; }
run_helper() { EXPECT_TARGET="$1" with_h "$BASH_RUN" "${2:-$helper}" "$1"; }
waitf() { n=0; while [ "$n" -lt 80 ] && [ ! -f "$1" ]; do sleep 0.05; n=$((n+1)); done; [ -f "$1" ] || { echo "FAIL missing ${1##*/}"; fail=$((fail+1)); }; }
waitp() { n=0; while [ "$n" -lt 80 ] && kill -0 "$1" 2>/dev/null; do sleep 0.05; n=$((n+1)); done; }
bg() { with_h exec "$BASH_RUN" "$1" smoke >"$2" 2>&1 & wp=$!; }
ed() { python3 -c 'import sys;s=open(sys.argv[1]).read();p,n=sys.argv[3],sys.argv[4];sys.exit(2) if s.count(p)!=1 else open(sys.argv[5],"w").write(s.replace(p,n,1) if sys.argv[2]=="r" else s[:s.find(p)+len(p)]+"\n"+n+"\n"+s[s.find(p)+len(p):])' "$1" "$2" "$3" "$4" "$5" && chmod +x "$5"; }
inj() { ed "${4:-$helper}" i "$2" "$3" "$1" || { echo "FAIL inj $2"; fail=$((fail+1)); printf '%s\n' '#!/bin/sh' 'exit 2' > "$1"; chmod +x "$1"; }; }
mark() { inj "$1" 'ec=$?' ': > "$RUNNER_TEMP/cleanup.mark"'; }
bar() { inj "$1" 'on_exit() {' ': > "$RUNNER_TEMP/cleanup.mark"; while [ ! -f "$RUNNER_TEMP/cleanup.go" ]; do sleep 0.05; done' "${2-}"; }
start_bg() { sleep 30 & sentinel=$!; rm -f "$scratch/rt/"*.pid "$scratch/rt/"*.mark "$scratch/rt/"*.go; set +e; bg "$1" "$2"; }
